create table p (id integer primary key, a integer, b varchar, unique (a, b)); create table "Q" ("Id" integer primary key, "Name" varchar unique); create table t (id integer primary key, n integer check (n > 0), p_id integer references p (id), u varchar unique collate nocase, q_id integer references "Q" ("Id"), "select" varchar check ("select" <> 'x'), unique (n, u), foreign key (n, b2) references p (a, b), b2 varchar, check (n < 100 or u like '%(,)%')); create table k (a integer, b integer, primary key (a, b), check (a <> b));
